import{_ as e,c as s,o as i,a4 as t}from"./chunks/framework.BX6rvgvq.js";const u=JSON.parse('{"title":"运行命令报错","description":"","frontmatter":{},"headers":[],"relativePath":"modules/more/vscode/运行命令报错.md","filePath":"modules/more/vscode/运行命令报错.md","lastUpdated":1774171177000}'),a={name:"modules/more/vscode/运行命令报错.md"},o=t('<h1 id="运行命令报错" tabindex="-1">运行命令报错 <a class="header-anchor" href="#运行命令报错" aria-label="Permalink to &quot;运行命令报错&quot;">​</a></h1><p>比如运行运行：<code>npm i</code>, 提示: <code>npm : 无法加载文件 C:\\Program Files\\nodejs\\npm.ps1，因为在此系统上禁止运行脚本。</code></p><p>PowerShell 执行策略是一项安全功能，用于控制 PowerShell 加载配置文件和运行脚本的条件。 此功能有助于防止恶意脚本的执行。</p><p><a href="https://learn.microsoft.com/zh-cn/powershell/module/microsoft.powershell.core/about/about_execution_policies?view=powershell-7.5" target="_blank" rel="noreferrer">PowerShell 执行策略如下：</a></p><ul><li>AllSigned - 脚本可以运行。</li><li>Bypass - 不阻止任何操作，并且没有任何警告或提示。</li><li>Default - 设置默认执行策略。</li><li>RemoteSigned - Windows 计算机的默认执行策略。脚本可以运行。</li><li>Restricted - 允许单个命令，但不允许脚本。阻止运行所有脚本文件，包括格式和配置文件 (.ps1xml)、模块脚本文件 (.psm1) 和 PowerShell 配置文件 (.ps1)。</li><li>Undefined - 当前范围内没有设置执行策略。</li><li>Unrestricted - 非 Windows 计算机的默认执行策略，不能更改。</li></ul><p>获取当前执行策略</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get-ExecutionPolicy</span></span></code></pre></div><p>返回<code>Restricted</code>说明不允许脚本运行。</p><p>修改策略</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Set-ExecutionPolicy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CurrentUser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RemoteSigned</span></span></code></pre></div><p>修改之后再获取当前策略，返回<code>RemoteSigned</code>说明修改成功。再执行<code>npm i</code></p>',11),l=[o];function n(p,d,c,r,h,_){return i(),s("div",null,l)}const g=e(a,[["render",n]]);export{u as __pageData,g as default};
